parameters.functionScript:
// Everything the panels need about the picked file, decided in one place, plus
// the only check that can be made before the network is involved.
//
// "Run on value change" is unticked for Max Size MB (runOnChange-in-MaxMB) so
// that editing the limit cannot re-answer a file that was already answered.
// File keeps it ticked on purpose: the arriving file IS the trigger.
const file = Inputs.File;
const maxMb = Number(Inputs.MaxMB) > 0 ? Number(Inputs.MaxMB) : 10;

const bytes = (n) => {
  const v = Number(n);
  if (!isFinite(v) || v < 0) return '';
  if (v < 1024) return v + ' B';
  if (v < 1024 * 1024) return (v / 1024).toFixed(1) + ' KB';
  return (v / (1024 * 1024)).toFixed(1) + ' MB';
};

// Every Function runs once at boot, before anybody has picked anything, and an
// unconnected input arrives as undefined rather than as its default.
//
// Fits is deliberately NOT written on that run. Writing it would publish a
// verdict on a file that does not exist, and the Condition beside this node
// re-tests on every change of its input — so booting the page would branch the
// component straight into its error state before anybody had touched it.
if (!file || typeof file.name !== 'string') {
  Outputs.Name = '';
  Outputs.Meta = '';
  Outputs.PreviewUrl = '';
  Outputs.IsImage = false;
  Outputs.NotImage = true;
  Outputs.Error = '';
  return;
}

const type = String(file.type || '');
const isImage = type.indexOf('image/') === 0;

Outputs.Name = file.name;
Outputs.Meta = [type || 'unknown type', bytes(file.size)].filter(Boolean).join(' \u00b7 ');
Outputs.IsImage = isImage;
Outputs.NotImage = !isImage;
// The preview costs no round trip and needs no backend, which is the whole
// reason it is worth having: you see the file before the upload can fail.
Outputs.PreviewUrl =
  isImage && typeof URL !== 'undefined' && URL.createObjectURL ? URL.createObjectURL(file) : '';

// The one failure that can be reported honestly without asking the server.
//
// The verdict is a BOOLEAN read by a Condition rather than a signal fired from
// here, and that is load-bearing twice over. A Function's signal outputs are
// declared in dynamicports, which a project loaded from disk does not deliver
// to the runtime — so Outputs.Accept() is not a function outside the editor. And
// Outputs publishes only on CHANGE, so a second acceptable file would re-write
// `true` over `true` and reach nobody. The Condition is pulsed by the picker's
// own Done instead, which happens once per pick whatever the answer is.
const fits = Number(file.size) <= maxMb * 1024 * 1024;

Outputs.Error = fits
  ? ''
  : file.name + ' is ' + bytes(file.size) + ' \u2014 the limit is ' + maxMb + ' MB.';
Outputs.Fits = fits;

// The bar, and the only place that knows a transfer has just started.
//
// Upload File's byte counts do not reset between uploads: they hold the LAST
// transfer's numbers until the first progress event of THIS one arrives. Wired
// straight through, the bar therefore opens the next upload at the previous
// file's 100% and walks backwards. State is read for exactly that reason, and
// Seen is this node's memory of which state it last drew.
const state = String(Inputs.State || '');
const pct = Math.max(0, Math.min(100, Number(Inputs.Percent) || 0));
const entering = state === 'Uploading' && Outputs.Seen !== 'Uploading';

Outputs.Seen = state;

if (state !== 'Uploading') {
  Outputs.Percent = 0;
  Outputs.Label = '';
  return;
}

if (entering) {
  Outputs.Percent = 0;
  Outputs.Label = 'Uploading\u2026';
  return;
}

Outputs.Percent = pct;
// A backend that reports no progress at all leaves this at 0 for the whole
// transfer, so 0 says "working", not "0% done".
Outputs.Label = pct > 0 ? Math.round(pct) + '%' : 'Uploading\u2026';

// The second line of the drop zone. It exists so the component states its own
// limits before anyone hits them, rather than after.
const custom = String(Inputs.Hint || '').trim();
if (custom) {
  Outputs.Hint = custom;
  return;
}

const accept = String(Inputs.Accept || '').trim();
const max = Number(Inputs.MaxMB) > 0 ? Number(Inputs.MaxMB) : 10;

// Accepted File Types is whatever <input accept> takes: ".csv, .png" or
// "image/*, application/pdf". Both are turned into words.
const kinds = accept
  ? accept
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean)
      .map((s) => (s.charAt(0) === '.' ? s.slice(1) : s.split('/').pop()))
      .map((s) => (s === '*' ? 'any' : s.toUpperCase()))
      .join(', ')
  : 'Any file';

Outputs.Hint = kinds + ' \u00b7 up to ' + max + ' MB';

// One sentence for the error panel, whichever of the three things went wrong.
//
// Order is not arbitrary. The local check is the only one that can be right
// about a file the server never saw, so it wins while it stands; Upload File's
// error comes next because it is the most recent thing to have happened; the
// picker's error is last because the node never clears it, so leaving it first
// would mask every later upload failure for the rest of the session.
const local = String(Inputs.LocalError || '').trim();
const upload = String(Inputs.UploadError || '').trim();
const picker = String(Inputs.PickerError || '').trim();
const status = Number(Inputs.Status || 0);

let message = local || upload || picker;

if (!message) {
  // A Failure with an empty reason is the transport failing before the request
  // left the app. Saying so is better than an empty red panel.
  message = 'The upload did not finish, and nothing said why. Check the backend this project is pointed at.';
} else if (message === upload && status) {
  message = message + ' (HTTP ' + status + ')';
}

Outputs.Message = message;

// What the backend actually stored. Content Type and Size are empty on a
// backend that does not report them and on a file read back out of a record
// property, so the line is built from what arrived rather than printing
// "undefined" at the user.
const name = String(Inputs.Name || '').trim();
const size = Number(Inputs.Size);

const parts = [];
if (name) parts.push(name);
if (isFinite(size) && size > 0) {
  parts.push(size < 1024 * 1024 ? (size / 1024).toFixed(1) + ' KB' : (size / (1024 * 1024)).toFixed(1) + ' MB');
}

Outputs.Line = parts.join(' \u00b7 ');
